'use strict';

var fromString = require( '@stdlib/buffer/from-string' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var Uint8Array = require( '@stdlib/array/uint8' );
var data = require( './fixtures/lapack.json' ).fixtures;
/**
* Decodes reference IEEE754 bits without rounding decimal fixtures.
* @private
* @param {string} hex - IEEE754 hexadecimal bits
* @returns {number} number
*/
function decode(hex) {
	var b;
	b = fromString(hex.match(/../g).reverse().join(''), 'hex');
	return b.readDoubleLE(0);
}
/**
* Checks numeric storage, distinguishing signed zeros and accepting NaN storage values.
* @private
* @param {TypedArray} a - actual storage
* @param {TypedArray} b - expected storage
* @returns {boolean} whether values match
*/
function equal(a, b) {
	var i;
	for (i = 0; i < a.length; i++) {
		if (a[i] !== b[i] && !(a[i] !== a[i] && b[i] !== b[i])) {
			return false;
		}
		if (a[i] === 0 && 1 / a[i] !== 1 / b[i]) {
			return false;
		}
	}
	return true;
}
/**
* Packs independent indexed views with typed-array byte offsets and guards.
* @private
* @param {Object} f - directional reference fixture
* @param {integer} sa1 - row stride
* @param {integer} sa2 - column stride
* @param {integer} se - E stride
* @param {integer} sp - pivot stride
* @returns {Object} arguments and whole-buffer expectations
*/
function pack(f, sa1, sa2, se, sp) {
	var expectedA;
	var expectedE;
	var originalP;
	var bytesA;
	var bytesE;
	var afull;
	var efull;
	var maskA;
	var maskE;
	var pfull;
	var alen;
	var elen;
	var plen;
	var piv;
	var ix;
	var oa;
	var oe;
	var op;
	var a;
	var e;
	var i;
	var j;
	var n;
	n = f.n;
	oa = 4 + (( sa1 < 0 ) ? -(n - 1) * sa1 : 0) + (( sa2 < 0 ) ? -(n - 1) * sa2 : 0);
	oe = 3 + (( se < 0 ) ? -(n - 1) * se : 0);
	op = 2 + (( sp < 0 ) ? -(n - 1) * sp : 0);
	alen = oa + (( sa1 > 0 ) ? ((n - 1)) * sa1 : 0) + (( sa2 > 0 ) ? ((n - 1)) * sa2 : 0) + 6;
	elen = oe + (( se > 0 ) ? ((n - 1)) * se : 0) + 5;
	plen = op + (( sp > 0 ) ? ((n - 1)) * sp : 0) + 4;
	afull = new Float64Array(alen + 6);
	efull = new Float64Array(elen + 6);
	pfull = new Int32Array(plen + 6);
	a = new Float64Array(afull.buffer, 24, alen);
	e = new Float64Array(efull.buffer, 24, elen);
	piv = new Int32Array(pfull.buffer, 12, plen);
	for (i = 0; i < afull.length; i++) {
		afull[i] = 1024.25 + i;
	}
	for (i = 0; i < efull.length; i++) {
		efull[i] = -1024.25 - i;
	}
	for (i = 0; i < pfull.length; i++) {
		pfull[i] = 701 + i;
	}
	maskA = [];
	maskE = [];
	for (j = 0; j < n; j++) {
		for (i = 0; i < n; i++) {
			ix = oa + (i * sa1) + (j * sa2);
			a[ix] = decode(f.input_a_hex_col_major[i + (j * n)]);
			if (( f.uplo === 'U' ) ? i <= j : i >= j) {
				maskA[3 + ix] = true;
			}
		}
		e[oe + (j * se)] = decode(f.input_e_hex[j]);
		piv[op + (j * sp)] = f.ipiv_signed_1based[j];
		if (f.way === 'C') {
			maskE[3 + oe + (j * se)] = true;
		}
	}
	expectedA = new Float64Array(afull);
	expectedE = new Float64Array(efull);
	originalP = new Int32Array(pfull);
	bytesA = new Uint8Array(new Uint8Array(afull.buffer));
	bytesE = new Uint8Array(new Uint8Array(efull.buffer));
	for (j = 0; j < n; j++) {
		for (i = 0; i < n; i++) {
			expectedA[3 + oa + (i * sa1) + (j * sa2)] = decode(f.output_a_hex_col_major[i + (j * n)]);
		}
		expectedE[3 + oe + (j * se)] = decode(f.output_e_hex[j]);
	}
	return {
		'args': [
			( f.uplo === 'U' ) ? 'upper' : 'lower',
			( f.way === 'C' ) ? 'convert' : 'revert',
			n,
			a,
			sa1,
			sa2,
			oa,
			e,
			se,
			oe,
			piv,
			sp,
			op
		],
		'a': afull,
		'e': efull,
		'p': pfull,
		'expectedA': expectedA,
		'expectedE': expectedE,
		'originalP': originalP,
		'maskA': maskA,
		'maskE': maskE,
		'bytesA': bytesA,
		'bytesE': bytesE
	};
}
/**
* Checks every byte outside the stored mutable envelope elements.
* @private
* @param {Float64Array} a - actual whole storage
* @param {Uint8Array} before - original bytes
* @param {Array} mask - writable element mask
* @returns {boolean} whether all guards retain their exact bits
*/
function guards(a, before, mask) {
	var bytes;
	var i;
	bytes = new Uint8Array(a.buffer);
	for (i = 0; i < bytes.length; i++) {
		if (!mask[((i - (i % 8))) / 8] && bytes[i] !== before[i]) {
			return false;
		}
	}
	return true;
}
/**
* Exercises both reference directions over independent signed layouts.
* @private
* @param {Object} t - assertion context
* @param {Function} fn - public interface
* @returns {void}
*/
function corpus(t, fn) {
	var strides;
	var state;
	var f;
	var i;
	var j;
	var n;
	for (i = 0; i < data.length; i++) {
		f = data[i];
		n = f.n;
		if (n === 0) {
			t.strictEqual(fn.ndarray(( f.uplo === 'U' ) ? 'upper' : 'lower', ( f.way === 'C' ) ? 'convert' : 'revert', 0, null, NaN, NaN, NaN, null, NaN, NaN, null, NaN, NaN), 0, f.id + ' empty no access');
			continue;
		}
		strides = [
			[
				1,
				n + 2
			],
			[
				n + 3,
				1
			],
			[
				2,
				(2 * n) + 3
			],
			[
				-1,
				n + 3
			],
			[
				1,
				-n - 3
			],
			[
				-2,
				(-2 * n) - 3
			],
			[
				3,
				(-3 * n) - 2
			],
			[
				-3,
				(3 * n) + 2
			]
		];
		for (j = 0; j < strides.length; j++) {
			state = pack(f, strides[j][0], strides[j][1], ( j % 2 ) ? -2 : 3, ( j % 2 ) ? -3 : 2);
			t.strictEqual(fn.ndarray.apply(null, state.args), 0, f.id + ' status ' + j);
			t.ok(equal(state.a, state.expectedA), f.id + ' A ' + j);
			t.ok(equal(state.e, state.expectedE), f.id + ' E ' + j);
			t.deepEqual(state.p, state.originalP, f.id + ' signed pivots ' + j);
			t.ok(guards(state.a, state.bytesA, state.maskA), f.id + ' A guards ' + j);
			t.ok(guards(state.e, state.bytesE, state.maskE), f.id + ' E guards ' + j);
		}
	}
}
module.exports = {
	'pack': pack,
	'equal': equal,
	'corpus': corpus,
	'fixtures': data
};
